    '                if not close(h,base.hessian_eV_A2,REFS["tolerances"]["model_hessian_abs_eV_A2"],REFS["tolerances"]["model_hessian_rel"]): raise ScientificFailure(f"independent analytic Hessian mismatch for {rid}")\n'
    '                # Translation and proper 90-degree rotation about the centroid.\n'
