    '                if not close(translated_e,tr.energy_eV,1e-6): raise ScientificFailure(f"translated energy mismatch {rid}")\n'
    '                if not close(item.get("translated_forces_eV_A"),tr.forces_eV_A,1e-6,1e-6): raise ScientificFailure(f"translated force mismatch {rid}")\n'
    '                if abs(tr.energy_eV-base.energy_eV)>REFS["tolerances"]["translation_energy_abs_eV"] or not close(tr.forces_eV_A,base.forces_eV_A,1e-6,1e-6): raise ScientificFailure(f"model translation invariance failed for {rid}")\n'
    '                if not close(rotated_e,rr.energy_eV,1e-6): raise ScientificFailure(f"rotated energy mismatch {rid}")\n'
    '                if not close(item.get("rotated_forces_eV_A"),rr.forces_eV_A,1e-6,1e-6): raise ScientificFailure(f"rotated force mismatch {rid}")\n'
    '                if abs(rr.energy_eV-base.energy_eV)>REFS["tolerances"]["rotation_energy_abs_eV"] or not close(rr.forces_eV_A,base.forces_eV_A@r.T,1e-6,1e-6): raise ScientificFailure(f"model rotation covariance failed for {rid}")\n'
    '                if not close(h,base.hessian_eV_A2,REFS["tolerances"]["model_hessian_abs_eV_A2"],REFS["tolerances"]["model_hessian_rel"]): raise ScientificFailure(f"unrotated Hessian mismatch {rid}")\n'
    '                if not close(hr,rr.hessian_eV_A2,REFS["tolerances"]["model_hessian_abs_eV_A2"],REFS["tolerances"]["model_hessian_rel"]) or not close(hr,cov,REFS["tolerances"]["rotation_hessian_abs_eV_A2"],REFS["tolerances"]["rotation_hessian_rel"]): raise ScientificFailure(f"rotated Hessian covariance mismatch {rid}")\n'
    '                # Requested zero-based components and exact central difference h.\n'
