    '                    ep=replay(evaluator,ap,False,f"{rid} finite-difference plus"); em=replay(evaluator,am,False,f"{rid} finite-difference minus"); actual_ef+=2\n'
    '                    fd_grad=(ep.energy_eV-em.energy_eV)/(2*step)\n'
    '                    grad_res=abs(cand_f.flat[flat]+fd_grad)\n'
    '                    if grad_res>REFS["tolerances"]["gradient_fd_abs_eV_A"]+REFS["tolerances"]["gradient_fd_rel"]*abs(cand_f.flat[flat]): raise ScientificFailure(f"F=-dE/dx finite-difference check failed {rid} {atom}{axis}")\n'
    '                    fd_col=-(ep.forces_eV_A-em.forces_eV_A).ravel()/(2*step)\n'
    '                    h_res=float(np.max(np.abs(base.hessian_eV_A2[:,flat]-fd_col)))\n'
    '                    if not close(base.hessian_eV_A2[:,flat],fd_col,REFS["tolerances"]["force_hessian_fd_abs_eV_A2"],REFS["tolerances"]["force_hessian_fd_rel"]): raise ScientificFailure(f"H=-dF/dx finite-difference check failed {rid} {atom}{axis}")\n'
    '                    row=diag[(rid,f"{atom}:{axis}")]\n'
    '                    energy_res=finite_scalar(row["energy_gradient_residual"],f"energy-gradient diagnostic {rid} {atom}{axis}")\n'
    '                    force_res=finite_scalar(row["force_hessian_residual"],f"force-Hessian diagnostic {rid} {atom}{axis}")\n'
    '                    translation_delta=finite_scalar(row["translation_delta_eV"],f"translation diagnostic {rid} {atom}{axis}")\n'
