    '                    if abs(energy_res-grad_res)>REFS["tolerances"]["reported_energy_residual_abs"] or abs(force_res-h_res)>REFS["tolerances"]["reported_force_hessian_residual_abs"]:\n'
    '                        raise ScientificFailure(f"diagnostics.csv does not report independently recomputed residuals for {rid} {atom}{axis}")\n'
    '                    if abs(translation_delta-(tr.energy_eV-base.energy_eV))>REFS["tolerances"]["reported_translation_residual_abs"]: raise ScientificFailure(f"translation diagnostic mismatch {rid}")\n'
    '                    if abs(rotation_res-float(np.max(np.abs(hr-cov))))>REFS["tolerances"]["reported_rotation_residual_abs"]: raise ScientificFailure(f"rotation diagnostic mismatch {rid}")\n'
    '                    all_metrics.append({"reaction_id":rid,"component":f"{atom}:{axis}","gradient_residual":grad_res,"hessian_fd_max_abs":h_res})\n'
    '            if actual_h>REFS["limits"]["hessian_calls_max"] or actual_ef>REFS["limits"]["energy_force_calls_max"]: raise ScientificFailure("independent verification exceeded case compute caps")\n'
    '            if finite_count(model_calls["hessian_calls"],"hessian_calls")!=actual_h:\n'
    '                raise ScientificFailure("reported Hessian call count does not match the four required independent replay points")\n'
    '            if not (final/"report.md").is_file() or not (final/"report.md").read_text().strip(): raise ScientificFailure("report.md missing or empty")\n'
    '            return emit("PASS","independent E/F/H, finite-difference and rigid-motion checks passed",reward=1,details={"verified_hessian_calls":actual_h,"verified_energy_force_calls":actual_ef,"metrics":all_metrics})\n'
    '        except InvalidEnvironment: raise\n'
    '        except ScientificFailure: raise\n'
    '        except Exception as exc: raise ScientificFailure(f"malformed candidate bundle: {type(exc).__name__}: {exc}")\n'
    '    except InvalidEnvironment as exc: return emit("ENV_INVALID",exc,code=2)\n'
    '    except ScientificFailure as exc: return emit("FAIL",exc,reward=0,code=1)\n'
    '    except Exception as exc: return emit("ENV_INVALID",f"scorer failure {type(exc).__name__}: {exc}",code=2)\n'
    '\n'
    'if __name__=="__main__": raise SystemExit(main(sys.argv))\n'
